def cobros_a_la_caja_tecnico(apps, schema_editor):
    """Los cobros de reparaciones que ya estaban registrados pasan a la caja del técnico (en efectivo)."""
    Reparacion = apps.get_model("inventario", "Reparacion")
    CajaMovimiento = apps.get_model("inventario", "CajaMovimiento")
    for r in Reparacion.objects.filter(cobrado_en__isnull=False, cobrado__isnull=False):
        CajaMovimiento.objects.create(
            caja="TECNICO", metodo="EFECTIVO", monto=r.cobrado, origen="REPARACION",
            concepto=f"Reparación R-{r.pk:04d}: {r.cliente}"[:200],
            usuario_id=r.cobrado_por_id, fecha=r.cobrado_en, reparacion=r,
        )


